import XCTest
import CryptoKit

final class BridgeDiscoveryTests: XCTestCase {
    // This vector was generated by Node crypto, independently of CryptoKit.
    private let fixture = #"{"id":"11111111-2222-4333-8444-555555555555","pollToken":"fixture-only-fixture-only-fixture-only-fixture-only-","code":"013112","expiresAt":"2026-10-17T20:00:00Z","serverPublicKey":"BFUPRxAD89+Xw99QaseX9nIfsaH7e49vg9IkSYplyI4kE2CT1wEuUJpzcVy9CwCjzA/0tcAbP/oZarH7MnA2uOY=","salt":"AwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwM=","encrypted":{"nonce":"BAQEBAQEBAQEBAQE","ciphertext":"b9/ZhnVUpYAWQ+nnq2Bb5tKdEs72eZ72MkQ9bpS33NdHCE+79Kr00Ed39KMrMjFnZwlh0VP4lsC1Kr7PG2NODuuNBb9sCSoCG5zDC9qvUvJ4mWIsl46TzxLPsStwnpWX+QndQIXAudxWLk/xS/Cq4Xnsk+zbD15BOkPSXtDDuTGwJ/VEBOoo0RjOAr8u2fIRGLerpr5GqISqXmXnh6BoDcoe4eu7xA+fON1xCqoY/f957qcsU9go7ZyNVHGDMG0z2I8uIgpb/vR9UhiLJ7f1d7o=","tag":"4jxFqI9Zd6rsHeBzj/48uw=="},"bridgeId":"2c9495a1268bf86f79c75ce1992bf0275666db92ed3c227c0c1794ee3acd4f0e"}"#

    private var bridge: DiscoveredBridge {
        DiscoveredBridge(id: "2c9495a1268bf86f79c75ce1992bf0275666db92ed3c227c0c1794ee3acd4f0e", name: "Fixture Mac", origin: URL(string: "http://100.80.90.10:3333")!)
    }

    func testNodePairingEnvelopeDecryptsAndBindsMacAndOrigin() throws {
        let data = Data(fixture.utf8)
        let challenge = try JSONDecoder().decode(WirelessPairingChallenge.self, from: data)
        let envelope = try JSONDecoder().decode(WirelessPairingPoll.self, from: Data(fixture.replacingOccurrences(of: "\"id\":", with: "\"state\":\"approved\",\"id\":").utf8)).encrypted!
        let key = WirelessPairingKey(privateKey: try P256.KeyAgreement.PrivateKey(rawRepresentation: Data(repeating: 1, count: 32)))
        let credentials = try key.decrypt(envelope, challenge: challenge, bridge: bridge)
        XCTAssertEqual(credentials.name, "Fixture Mac")
        XCTAssertEqual(PairedBridge(credentials.baseURL)?.identity, bridge.id)
        let wrongOrigin = DiscoveredBridge(id: bridge.id, name: bridge.name, origin: URL(string: "http://100.80.90.11:3333")!)
        XCTAssertThrowsError(try key.decrypt(envelope, challenge: challenge, bridge: wrongOrigin))
        let wrongID = DiscoveredBridge(id: String(repeating: "0", count: 64), name: bridge.name, origin: bridge.origin)
        XCTAssertThrowsError(try key.decrypt(envelope, challenge: challenge, bridge: wrongID))
    }

    func testChangedKeyOrConfirmationCodeCannotPair() throws {
        let key = WirelessPairingKey(privateKey: try P256.KeyAgreement.PrivateKey(rawRepresentation: Data(repeating: 1, count: 32)))
        let challenge = try JSONDecoder().decode(WirelessPairingChallenge.self, from: Data(fixture.utf8))
        XCTAssertNoThrow(try key.verifiedKey(challenge))
        XCTAssertThrowsError(try WirelessPairingKey().verifiedKey(challenge))
        let changed = try JSONDecoder().decode(WirelessPairingChallenge.self, from: Data(fixture.replacingOccurrences(of: "013112", with: "013113").utf8))
        XCTAssertThrowsError(try key.verifiedKey(changed))
    }

    func testDiscoveryRejectsPublicCredentialAndMalformedOrigins() {
        XCTAssertTrue(bridge.isValid)
        XCTAssertTrue(DiscoveredBridge.allowedOrigin(URL(string: "http://fixture-mac.tail-example.ts.net:3333")!))
        XCTAssertEqual(DiscoveredBridge(id: bridge.id, name: bridge.name, origin: URL(string: "http://fixture-mac.tail-example.ts.net:3333")!).route, .tailscale)
        for raw in ["http://example.com:3333", "http://127.0.0.1:3333", "http://100.80.90.10:3333/device/secret", "http://100.80.90.10:3333?token=secret", "http://u:p@100.80.90.10:3333", "http://100.80.90.10", "http://100.080.90.10:3333"] {
            XCTAssertFalse(DiscoveredBridge.allowedOrigin(URL(string: raw)!), raw)
        }
        for host in ["ts.net", "example.ts.net", "host..ts.net", "host.tail-example.ts.net.evil.com", "-host.tail.ts.net", "host.tail-.ts.net"] {
            XCTAssertFalse(PairedBridge.isTailscaleDNSName(host), host)
        }
    }

    func testDiscoveryProbeIsTokenFreeAndFiltersUntrustedDirectory() async throws {
        let origin = bridge.origin
        let reply = "{\"version\":1,\"bridge\":{\"id\":\"\(bridge.id)\",\"name\":\"Fixture Mac\",\"origin\":\"\(origin)\"},\"bridges\":[],\"tailscale\":{\"state\":\"running\",\"availablePeers\":1}}"
        let client = BridgeDiscoveryClient(send: { request in
            XCTAssertEqual(request.url?.absoluteString, "\(origin)/api/bridge/discovery?self=1")
            XCTAssertNil(request.value(forHTTPHeaderField: "Authorization"))
            XCTAssertNil(request.value(forHTTPHeaderField: "X-Pairing-Token"))
            return (Data(reply.utf8), HTTPURLResponse(url: request.url!, statusCode: 200, httpVersion: nil, headerFields: nil)!)
        })
        let response = try await client.discover(at: origin, selfOnly: true)
        XCTAssertEqual(response.bridge, bridge)
    }

    @MainActor
    func testFreshInstallationDiscoversFromTailnetSeedWithoutPairedURL() async throws {
        let suite = "WirelessDiscovery.\(UUID())"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let bridge = bridge
        let reply = "{\"version\":1,\"bridge\":{\"id\":\"\(bridge.id)\",\"name\":\"Fixture Mac\",\"origin\":\"\(bridge.origin)\"},\"bridges\":[],\"tailscale\":{\"state\":\"running\",\"availablePeers\":1}}"
        let model = BridgeDiscoveryModel(client: BridgeDiscoveryClient(send: { request in
            XCTAssertEqual(request.url?.host, bridge.origin.host)
            return (Data(reply.utf8), HTTPURLResponse(url: request.url!, statusCode: 200, httpVersion: nil, headerFields: nil)!)
        }), seeds: [bridge.origin], defaults: defaults)
        await model.refresh()
        XCTAssertEqual(model.bridges, [bridge])
        XCTAssertTrue(model.discoveryStatus.contains("Tailscale directory reachable"))
        XCTAssertNil(defaults.string(forKey: "serverURLString"), "Discovery must not silently authorize a Mac")
        XCTAssertNil(model.pairedURL)
    }

    @MainActor
    func testLANDiscoveryDoesNotClaimTheIPadReachedTailscale() async throws {
        let suite = "WirelessDiscovery.LAN.\(UUID())"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let origin = URL(string: "http://fixture-mac.local:3333")!
        let reply = "{\"version\":1,\"bridge\":{\"id\":\"\(bridge.id)\",\"name\":\"Fixture Mac\",\"origin\":\"\(origin)\"},\"bridges\":[],\"tailscale\":{\"state\":\"running\",\"availablePeers\":1}}"
        let model = BridgeDiscoveryModel(client: BridgeDiscoveryClient(send: { request in
            (Data(reply.utf8), HTTPURLResponse(url: request.url!, statusCode: 200, httpVersion: nil, headerFields: nil)!)
        }), seeds: [origin], defaults: defaults)
        await model.refresh()
        XCTAssertFalse(model.discoveryStatus.contains("Tailscale directory reachable"))
        XCTAssertTrue(model.discoveryStatus.contains("Nearby Mac bridges found"))
    }
    @MainActor
    func testSavedMacReconnectsWithoutAnotherPairingAndPreservesDurableURL() async throws {
        let suite = "SavedMacs.\(UUID())"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let durable = URL(string: "http://old-mac.local:3333/device/" + String(repeating: "a", count: 32))!
        let paired = PairedBridge(durable)!
        defaults.set(durable.absoluteString, forKey: "localURLString")
        let origin = URL(string: "http://100.80.90.10:3333")!
        let discovered = DiscoveredBridge(id: paired.identity, name: "Saved Mac", origin: origin)
        let transport = BridgeTransport(defaults: defaults, send: { request in
            let url = request.url!
            XCTAssertEqual(request.httpMethod, "GET", "Reconnect must not request new pairing approval")
            let data: Data
            if url.path == "/api/bridge/identity" {
                XCTAssertFalse(url.path.contains("/device/"))
                let nonce = URLComponents(url: url, resolvingAgainstBaseURL: false)!.queryItems!.first { $0.name == "nonce" }!.value!
                data = try JSONSerialization.data(withJSONObject: ["id": paired.identity, "nonce": nonce,
                    "origin": origin.absoluteString, "proof": paired.hmac("petroglyphs-bridge-proof-v1\n\(nonce)\n\(origin.absoluteString)\n\(paired.identity)")])
            } else {
                XCTAssertEqual(url.path, "/device/" + paired.token + "/api/health")
                data = try JSONEncoder().encode(HealthResponse(status: "ok", version: "test", submissions: 0, autoReply: nil,
                    bridge: BridgeConnectionMetadata(version: 1, id: paired.identity, lanOrigins: [], tailscaleOrigins: [origin])))
            }
            return (data, HTTPURLResponse(url: url, statusCode: 200, httpVersion: nil, headerFields: nil)!)
        })
        let model = BridgeDiscoveryModel(seeds: [], defaults: defaults, transport: transport)
        XCTAssertTrue(model.isPaired(discovered))
        await model.connect(to: discovered)
        XCTAssertEqual(model.pairedURL, durable)
        XCTAssertEqual(defaults.string(forKey: "serverURLString"), durable.absoluteString)
        let restored = BridgeDiscoveryModel(seeds: [], defaults: defaults, transport: transport)
        XCTAssertTrue(restored.isPaired(discovered), "Approved Macs survive restart")
    }

    @MainActor
    func testRegistryKeepsBothMacsAndOriginalURLWhenPairingAgain() throws {
        let suite = "SavedMacRegistry.\(UUID())"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let a = URL(string: "http://mac-a.local:3333/device/" + String(repeating: "a", count: 32))!
        let b = URL(string: "http://mac-b.local:3333/device/" + String(repeating: "b", count: 32))!
        defaults.set(a.absoluteString, forKey: "localURLString")
        defaults.set(b.absoluteString, forKey: "serverURLString")
        var registry = SavedBridgeRegistry(defaults: defaults)
        XCTAssertEqual(registry.bridges.count, 2)
        let changedOrigin = URL(string: "http://100.80.90.10:3333/device/" + String(repeating: "a", count: 32))!
        registry.remember(url: changedOrigin, name: "Renamed Mac")
        let restored = SavedBridgeRegistry(defaults: defaults)
        XCTAssertEqual(restored[PairedBridge(a)!.identity]?.durableURL, a)
        XCTAssertEqual(restored[PairedBridge(a)!.identity]?.name, "Renamed Mac")
        XCTAssertEqual(restored[PairedBridge(b)!.identity]?.durableURL, b)
    }

    @MainActor
    func testFailedAndCancelledSwitchKeepThePreviousConnection() async throws {
        let suite = "SavedMacCancelled.\(UUID())"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let fixture = SavedMacSwitchFixture()
        let a = fixture.mac("a")
        let b = fixture.mac("b")
        var registry = SavedBridgeRegistry(defaults: defaults)
        registry.remember(url: a.baseURL, name: "A")
        registry.remember(url: b.baseURL, name: "B")
        defaults.set(a.baseURL.absoluteString, forKey: "serverURLString")
        let transport = BridgeTransport(defaults: defaults, send: { try await fixture.send($0) })
        let model = BridgeDiscoveryModel(seeds: [], defaults: defaults, transport: transport)
        let discovered = DiscoveredBridge(id: b.identity, name: "B", origin: b.origin)
        await fixture.rejectIdentity(b.identity)
        await model.connect(to: discovered)
        XCTAssertNotNil(model.error)
        XCTAssertEqual(defaults.string(forKey: "serverURLString"), a.baseURL.absoluteString)
        XCTAssertEqual(model.connectionRevision, 0)
        let failedCalls = await fixture.requests()
        XCTAssertFalse(failedCalls.contains { $0.url?.path.contains("/device/") == true })

        await fixture.holdNextHealth()
        let operation = Task { await model.connect(to: discovered) }
        await fixture.waitForHeldHealth()
        model.cancelPairing()
        await fixture.releaseHealth()
        await operation.value
        XCTAssertNil(model.pairedURL)
        XCTAssertEqual(defaults.string(forKey: "serverURLString"), a.baseURL.absoluteString)
        XCTAssertEqual(model.connectionRevision, 0)
    }

    @MainActor
    func testLateSwitchCannotReplaceTheNewerMacSelection() async throws {
        let suite = "SavedMacRace.\(UUID())"
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite) }
        let fixture = SavedMacSwitchFixture()
        let a = fixture.mac("a")
        let b = fixture.mac("b")
        var registry = SavedBridgeRegistry(defaults: defaults)
        registry.remember(url: a.baseURL, name: "A")
        registry.remember(url: b.baseURL, name: "B")
        let transport = BridgeTransport(defaults: defaults, send: { try await fixture.send($0) })
        let model = BridgeDiscoveryModel(seeds: [], defaults: defaults, transport: transport)
        await fixture.holdNextHealth()
        let first = Task { await model.connect(to: DiscoveredBridge(id: a.identity, name: "A", origin: a.origin)) }
        await fixture.waitForHeldHealth()
        await model.connect(to: DiscoveredBridge(id: b.identity, name: "B", origin: b.origin))
        await fixture.releaseHealth()
        await first.value
        XCTAssertEqual(model.pairedURL, b.baseURL)
        XCTAssertEqual(model.connectionRevision, 1)
        XCTAssertEqual(defaults.string(forKey: "serverURLString"), b.baseURL.absoluteString)
    }

}


private actor SavedMacSwitchFixture {
    private var rejected: String?
    private var holdHealth = false
    private var held: CheckedContinuation<Void, Never>?
    private var waiters: [CheckedContinuation<Void, Never>] = []
    private var calls: [URLRequest] = []

    nonisolated func mac(_ letter: String) -> PairedBridge {
        PairedBridge(URL(string: "http://mac-\(letter).local:3333/device/" + String(repeating: letter, count: 32))!)!
    }
    func rejectIdentity(_ id: String) { rejected = id }
    func holdNextHealth() { rejected = nil; holdHealth = true }
    func requests() -> [URLRequest] { calls }
    func waitForHeldHealth() async {
        if held != nil { return }
        await withCheckedContinuation { waiters.append($0) }
    }
    func releaseHealth() { held?.resume(); held = nil }
    func send(_ request: URLRequest) async throws -> (Data, URLResponse) {
        calls.append(request)
        let url = request.url!
        let bridge = mac(url.host == "mac-a.local" ? "a" : "b")
        let data: Data
        if url.path == "/api/bridge/identity" {
            let nonce = URLComponents(url: url, resolvingAgainstBaseURL: false)!.queryItems!.first { $0.name == "nonce" }!.value!
            data = try JSONSerialization.data(withJSONObject: ["id": bridge.identity, "nonce": nonce,
                "origin": bridge.origin.absoluteString,
                "proof": rejected == bridge.identity ? "invalid" : bridge.hmac("petroglyphs-bridge-proof-v1\n\(nonce)\n\(bridge.origin.absoluteString)\n\(bridge.identity)")])
        } else {
            if holdHealth {
                holdHealth = false
                await withCheckedContinuation { continuation in
                    held = continuation
                    let current = waiters; waiters = []
                    current.forEach { $0.resume() }
                }
            }
            data = try JSONEncoder().encode(HealthResponse(status: "ok", version: "test", submissions: 0, autoReply: nil,
                bridge: BridgeConnectionMetadata(version: 1, id: bridge.identity, lanOrigins: [bridge.origin], tailscaleOrigins: [])))
        }
        return (data, HTTPURLResponse(url: url, statusCode: 200, httpVersion: nil, headerFields: nil)!)
    }
}
